-- Update 17: new Ammos photos (hero, story, fan, beach club) + menu links go to the live online menu
-- hero: new bar photo (phone gets the portrait version) + keep the sunset slide; second button → online menu
UPDATE "site_content" SET "data" = "data" || '{"mediaType": "slideshow", "slides": [{"image": "/images/ig/hero-bar.webp", "mobileImage": "/images/ig/hero-bar-phone.webp", "position": "center 60%"}, {"image": "/images/ig/hero-sunset.webp", "position": "center 55%"}], "image": "/images/ig/hero-bar.webp", "secondaryUrl": "https://ammos-beach-bar.nina.cy/?step=menu"}'::jsonb WHERE "key" = 'home.hero';--> statement-breakpoint
-- header links + full-screen menu: every "/menu" link → online menu, new tab
UPDATE "site_content" SET "data" = jsonb_set("data", '{headerLinks}', (SELECT jsonb_agg(CASE WHEN e->>'url' IN ('/menu', '/menu/') THEN e || '{"url": "https://ammos-beach-bar.nina.cy/?step=menu", "newTab": true}'::jsonb ELSE e END ORDER BY o) FROM jsonb_array_elements("data"->'headerLinks') WITH ORDINALITY AS t(e, o))) WHERE "key" = 'navigation' AND jsonb_typeof("data"->'headerLinks') = 'array' AND jsonb_array_length("data"->'headerLinks') > 0;--> statement-breakpoint
UPDATE "site_content" SET "data" = jsonb_set("data", '{menuLinks}', (SELECT jsonb_agg(CASE WHEN e->>'url' IN ('/menu', '/menu/') THEN e || '{"url": "https://ammos-beach-bar.nina.cy/?step=menu", "newTab": true}'::jsonb ELSE e END ORDER BY o) FROM jsonb_array_elements("data"->'menuLinks') WITH ORDINALITY AS t(e, o))) WHERE "key" = 'navigation' AND jsonb_typeof("data"->'menuLinks') = 'array' AND jsonb_array_length("data"->'menuLinks') > 0;--> statement-breakpoint
-- story page: top photo + chapter photos (only where the old built-in photo is still used)
UPDATE "site_content" SET "data" = "data" || '{"heroImage": "/images/ig/hero-bar.webp"}'::jsonb WHERE "key" = 'page.story' AND "data"->>'heroImage' = '/images/awards-interior.jpg';--> statement-breakpoint
UPDATE "site_content" SET "data" = jsonb_set("data", '{chapters}', (SELECT jsonb_agg(CASE e->>'image' WHEN '/images/party.jpg' THEN e || '{"image": "/images/ig/story-entrance.webp"}'::jsonb WHEN '/images/bartender.jpg' THEN e || '{"image": "/images/ig/bar-glasses.webp"}'::jsonb ELSE e END ORDER BY o) FROM jsonb_array_elements("data"->'chapters') WITH ORDINALITY AS t(e, o))) WHERE "key" = 'page.story' AND jsonb_typeof("data"->'chapters') = 'array' AND jsonb_array_length("data"->'chapters') > 0;--> statement-breakpoint
-- homepage fanned photos: "Inside Ammos" → the swing
UPDATE "site_content" SET "data" = jsonb_set("data", '{fan}', (SELECT jsonb_agg(CASE WHEN e->>'image' = '/images/ig/fan-interior.webp' THEN e || '{"image": "/images/ig/fan-swing.webp", "alt": "The Ammos swing under the logo wall"}'::jsonb ELSE e END ORDER BY o) FROM jsonb_array_elements("data"->'fan') WITH ORDINALITY AS t(e, o))) WHERE "key" = 'home.story' AND jsonb_typeof("data"->'fan') = 'array' AND jsonb_array_length("data"->'fan') > 0;--> statement-breakpoint
-- homepage activities: Beach club → the Ammos towel
UPDATE "site_content" SET "data" = jsonb_set("data", '{polaroids}', (SELECT jsonb_agg(CASE WHEN e->>'image' = '/images/ig/beach-club.webp' THEN e || '{"image": "/images/ig/beach-towel.webp"}'::jsonb ELSE e END ORDER BY o) FROM jsonb_array_elements("data"->'polaroids') WITH ORDINALITY AS t(e, o))) WHERE "key" = 'home.activities' AND jsonb_typeof("data"->'polaroids') = 'array' AND jsonb_array_length("data"->'polaroids') > 0;
